<?php
namespace Tests\Feature\BulkImport;
use App\Domain\BulkImport\Enums\MigrationItemStatus;use App\Domain\BulkImport\Services\MigrationItemValidator;use App\Models\{District,DocumentCategory,DocumentType,MigrationBatch,MigrationBatchItem,RevenueCircle,State,User};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Str;use Tests\TestCase;
class MigrationItemValidatorTest extends TestCase{use RefreshDatabase;public function test_invalid_circle_district_relationship_is_rejected():void{$this->seed();$u=User::factory()->create();$s=State::where('code','AS')->first();$d1=District::create(['ulid'=>(string)Str::ulid(),'state_id'=>$s->id,'code'=>'D1','name_en'=>'D1']);$d2=District::create(['ulid'=>(string)Str::ulid(),'state_id'=>$s->id,'code'=>'D2','name_en'=>'D2']);$c=RevenueCircle::create(['ulid'=>(string)Str::ulid(),'district_id'=>$d2->id,'code'=>'C2','name_en'=>'C2']);$cat=DocumentCategory::create(['code'=>'LAND','name_en'=>'Land']);$type=DocumentType::create(['document_category_id'=>$cat->id,'code'=>'JAM','name_en'=>'Jamabandi']);$b=MigrationBatch::create(['ulid'=>(string)Str::ulid(),'batch_reference'=>'MIG-T','template_version'=>'v1','original_manifest_name'=>'x.csv','manifest_sha256'=>str_repeat('a',64),'status'=>'UPLOADED','created_by'=>$u->id]);$i=MigrationBatchItem::create(['migration_batch_id'=>$b->id,'external_row_id'=>'1','source_row_number'=>2,'source_payload'=>['document_type_code'=>'JAM','district_code'=>'D1','revenue_circle_code'=>'C2','title'=>'X'],'status'=>MigrationItemStatus::Pending]);app(MigrationItemValidator::class)->validate($i);$i->refresh();$this->assertSame(MigrationItemStatus::Invalid,$i->status);$this->assertContains('CIRCLE_DISTRICT_MISMATCH',$i->errors);}}
